from pathlib import Path
import json,hashlib
r=Path(__file__).resolve().parent.parent
base=json.loads((r/'verification_regression_R10_on_R11.json').read_text());assert base['total_fresh_simulation_runs']==125
names=['irq_r11','irq_unit_r11','return_guard_r11','no_diag_r11','timing_platform','timing_legacy','cdc_r11_2','exsp_work_r11_2']
parts={n:json.loads((r/('verification_'+n+'_result.json')).read_text()) for n in names};counts={n:j.get('fresh_runs',j.get('runs',0)) for n,j in parts.items()}
assert counts==dict(irq_r11=41,irq_unit_r11=18,return_guard_r11=17,no_diag_r11=4,timing_platform=3,timing_legacy=4,cdc_r11_2=9,exsp_work_r11_2=12),counts
paths=[p for p in (r/'fpga').rglob('*') if p.is_file()]+list((r/'hardware_test').glob('*.COM'))
j=dict(series='restart R11.2',purpose='CPU decode/EXSP work registers and guarded SDRAM capture; no new instruction features',major_function_stage=7,timing_work_stage=10,R10_compatible_regression_runs=125,new_runs=counts,total_fresh_simulation_runs=125+sum(counts.values()),expected_failure_runs=base['expected_failure_runs']+parts['cdc_r11_2']['expected_failure_runs'],all_cases_executed_this_revision=True,verification_scope='CPU/bridge/controller regression and isolated platform tests; full top not simulated',PC_bits=24,SPS_bits=16,SPL_bits=24,I_bits=16,ADL_reset=0,preloaded_20_COM_unchanged=True,EXSP_source_and_address_work_registers=True,EXSP_interrupts_deferred_and_WAIT_hold_verified=True,SDRAM_payload_minimum_capture_receiver_cycles=3,SDRAM_payload_stable_until_ack_verified=True,no_new_or_relaxed_timing_exceptions=True,native_ADL_IM1_IM2_NMI_RETI_RETN=True,MBASE_MADL_mixed_frames_implemented=False,R11_1_user_report=dict(GOWIN_success=True,Logic=17945,CLS=9804,BSRAM=44,SofaRun_Space_Manbow_play=True,unimplemented_six_tests_NOT_READY=True,all_other_RUNALL_results_not_explicitly_reported=True),GOWIN_run_for_this_revision=False,hardware_run_for_this_revision=False,timing_closure_for_this_revision=False,area_for_this_revision_measured=False,ROM_attribute_mapping_verified_in_GOWIN=False,PR1014_resolution_unverified=True,full_MSX_DOS_BIOS_simulated=False,sha256={str(p.relative_to(r)):hashlib.sha256(p.read_bytes()).hexdigest() for p in paths})
assert j['total_fresh_simulation_runs']==233 and j['expected_failure_runs']==6
(r/'verification_result.json').write_text(json.dumps(j,indent=2)+'\n');print('PASS R11.2 aggregate 233 positive scenarios + 6 expected failures')
